pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount, address logAddr) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        c.SetLogFile(logAddr);
        c.Initialized();
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        // General rule: once configured, a deposit must succeed (Log set properly);
        // the mutant leaves Log = 0 so Deposit reverts for some inputs.
        assertTrue(ok);
    }
}

