pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address logAddr, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(logAddr != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        c.SetLogFile(logAddr);
        vm.deal(actor, amount);

        vm.prank(actor);
        try c.Deposit{value: amount}() {
            assertTrue(true);
        } catch {
            assertTrue(false, "Deposit must succeed once a log file is set");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address _log) public {
        // admissible domain: a real (nonzero) log-file address
        vm.assume(_log != address(0));

        // drive c through SetLogFile while it is still uninitialized
        c.SetLogFile(_log);

        // reference stores the supplied address; mutant stores address(0)
        assertTrue(address(c.Log()) == _log);
    }
}

