contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint x, uint y) public payable {
        require(y > 0, "y must be nonzero");
        require(y <= type(uint256).max - x, "no overflow for mutant");
        c.SetMinSum(x);
        c.SetMinSum(y);
        assert(c.MinSum() == y);
    }
    receive() external payable {}
}

